function getFTS5DbPath(kgName: string): string {
  const cacheDir = path.join(homedir(), ".claude", "kg-fts5");
  fs.mkdirSync(cacheDir, { recursive: true });
  return path.join(cacheDir, `${kgName}.db`);
}
